<?php
namespace App\Controllers;
use App\Libraries\ShopStore;
use CodeIgniter\Exceptions\PageNotFoundException;

class Shop extends BaseController
{
    private function store(): ShopStore { return new ShopStore(); }
    private function render(string $page, array $data=[]): string { return view('shop', array_merge(['page'=>$page,'cartCount'=>array_sum(session()->get('cart') ?? [])],$data)); }
    private function admin() { if(session()->get('role') !== 'admin') throw PageNotFoundException::forPageNotFound(); }
    public function index() { $store=$this->store(); $q=trim((string)$this->request->getGet('q')); $category=trim((string)$this->request->getGet('category')); $sql='SELECT * FROM products WHERE active=1'; $args=[]; if($q!==''){ $sql.=' AND (name LIKE ? OR description LIKE ?)'; $args[]='%'.$q.'%'; $args[]='%'.$q.'%'; } if(in_array($category,['Icepops','Gelato'],true)){ $sql.=' AND category=?'; $args[]=$category; } $s=$store->db->prepare($sql.' ORDER BY id'); $s->execute($args); return $this->render('catalog',['products'=>$s->fetchAll(),'q'=>$q,'category'=>$category]); }
    public function product($id) { $p=$this->store()->product((int)$id); if(!$p) throw PageNotFoundException::forPageNotFound(); return $this->render('product',['product'=>$p]); }
    public function cart() { return $this->render('cart',['items'=>$this->store()->cart(session()->get('cart')??[])]); }
    public function add($id) { $p=$this->store()->product((int)$id); $qty=filter_var($this->request->getPost('quantity'),FILTER_VALIDATE_INT); $cart=session()->get('cart')??[]; if(!$p || !$qty || $qty<1 || ($cart[$id]??0)+$qty>$p['stock']) return redirect()->back()->with('error','Jumlah melebihi stok yang tersedia.'); $cart[$id]=($cart[$id]??0)+$qty; session()->set('cart',$cart); return redirect()->to(site_url('cart'))->with('success','Produk ditambahkan ke keranjang.'); }
    public function updateCart() { $cart=session()->get('cart')??[]; $action=(string)$this->request->getPost('action'); $id=(int)$this->request->getPost('id'); if($action==='clear') $cart=[]; elseif($action==='remove') unset($cart[$id]); else { $p=$this->store()->product($id); $qty=filter_var($this->request->getPost('quantity'),FILTER_VALIDATE_INT); if(!$p || !$qty || $qty<1 || $qty>$p['stock']) return redirect()->back()->with('error','Jumlah harus sesuai stok yang tersedia.'); if(isset($cart[$id])) $cart[$id]=$qty; } session()->set('cart',$cart); return redirect()->to(site_url('cart')); }
    public function checkout() { $items=$this->store()->cart(session()->get('cart')??[]); if(!$items)return redirect()->to(site_url('cart')); return $this->render('checkout',['items'=>$items]); }
    public function placeOrder() { $data=['recipient'=>trim((string)$this->request->getPost('recipient')),'whatsapp'=>trim((string)$this->request->getPost('whatsapp')),'address'=>trim((string)$this->request->getPost('address'))]; if(mb_strlen($data['recipient'])<2 || mb_strlen($data['recipient'])>100 || !preg_match('/^[+0-9 ()-]{8,25}$/',$data['whatsapp']) || mb_strlen($data['address'])<5 || mb_strlen($data['address'])>500) return redirect()->back()->withInput()->with('error','Isi nama, nomor WhatsApp, dan alamat dengan benar.'); try { $order=$this->store()->checkout(session()->get('cart')??[],$data,session()->get('shop_customer_id') ? (int)session()->get('shop_customer_id') : null); } catch(\RuntimeException $e) { return redirect()->to(site_url('cart'))->with('error',$e->getMessage()); } session()->remove('cart'); return redirect()->to(site_url('invoice/'.$order['invoice']).'?token='.$order['token']); }
    public function invoice($invoice) { $o=$this->store()->order($invoice); if(!$o)throw PageNotFoundException::forPageNotFound(); $token=(string)$this->request->getGet('token'); if(session()->get('role')!=='admin' && !($o['customer_id'] && (int)$o['customer_id']===(int)session()->get('shop_customer_id')) && !hash_equals($o['access_token'],$token)) throw PageNotFoundException::forPageNotFound(); return $this->render('invoice',['order'=>$o]); }
    public function account() { return $this->render('account'); }
    public function register() { $name=trim((string)$this->request->getPost('name')); $email=strtolower(trim((string)$this->request->getPost('email'))); $pass=(string)$this->request->getPost('password'); if(mb_strlen($name)<2 || mb_strlen($name)>100 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>190 || strlen($pass)<8 || strlen($pass)>72) return redirect()->back()->withInput()->with('error','Isi nama dan email yang valid; kata sandi minimal 8 karakter.'); try { $s=$this->store()->db->prepare('INSERT INTO customers (name,email,password_hash) VALUES (?,?,?)'); $s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]); } catch(\PDOException $e) { if($e->getCode() !== '23000') throw $e; return redirect()->back()->with('error','Email sudah terdaftar.'); } return redirect()->to(site_url('account'))->with('success','Akun dibuat. Silakan masuk.'); }
    public function login() { $s=$this->store()->db->prepare('SELECT * FROM customers WHERE email=?'); $s->execute([strtolower(trim((string)$this->request->getPost('email')))]); $u=$s->fetch(); if(!$u || !password_verify((string)$this->request->getPost('password'),$u['password_hash'])) return redirect()->back()->with('error','Email atau kata sandi salah.'); session()->regenerate(true); session()->set(['shop_customer_id'=>$u['id'],'shop_customer_name'=>$u['name']]); return redirect()->to(site_url('orders')); }
    public function logout() { session()->remove(['shop_customer_id','shop_customer_name']); session()->regenerate(true); return redirect()->to(site_url('/')); }
    public function orders() { if(!session()->get('shop_customer_id')) return redirect()->to(site_url('account')); $s=$this->store()->db->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC'); $s->execute([session()->get('shop_customer_id')]); return $this->render('orders',['orders'=>$s->fetchAll()]); }
    public function adminDashboard() { $this->admin(); $db=$this->store()->db; return $this->render('admin',['products'=>$db->query('SELECT * FROM products WHERE active=1 ORDER BY id DESC')->fetchAll(),'orders'=>$db->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll(),'revenue'=>$db->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Completed'")->fetchColumn()]); }
    public function productForm($id=null) { $this->admin(); $p=$id ? $this->store()->product((int)$id) : null; if($id && !$p)throw PageNotFoundException::forPageNotFound(); return $this->render('product_form',['product'=>$p]); }
    public function saveProduct($id=null) { $this->admin(); $store=$this->store(); $p=$id?$store->product((int)$id):null; if($id && !$p)throw PageNotFoundException::forPageNotFound(); $name=trim((string)$this->request->getPost('name')); $desc=trim((string)$this->request->getPost('description')); $cat=(string)$this->request->getPost('category'); $price=filter_var($this->request->getPost('price'),FILTER_VALIDATE_INT); $stock=filter_var($this->request->getPost('stock'),FILTER_VALIDATE_INT); if($name==='' || mb_strlen($name)>100 || $desc==='' || mb_strlen($desc)>1000 || !in_array($cat,['Icepops','Gelato'],true) || $price===false || $price<0 || $stock===false || $stock<0) return redirect()->back()->withInput()->with('error','Periksa kembali data produk.'); $image=$p['image']??null; $file=$this->request->getFile('image'); if($file && $file->getError()!==UPLOAD_ERR_NO_FILE) { if(!$file->isValid() || $file->getSize()>3*1024*1024 || !in_array($file->getMimeType(),['image/jpeg','image/png','image/webp'],true)) return redirect()->back()->withInput()->with('error','Foto harus JPEG, PNG, atau WebP dan maksimal 3 MB.'); $extension=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$file->getMimeType()]; $image=bin2hex(random_bytes(16)).'.'.$extension; $file->move(FCPATH.'uploads/products',$image); } if($id){$s=$store->db->prepare('UPDATE products SET name=?,description=?,category=?,price=?,stock=?,image=? WHERE id=?');$s->execute([$name,$desc,$cat,$price,$stock,$image,$id]);}else{$s=$store->db->prepare('INSERT INTO products (name,description,category,price,stock,image) VALUES (?,?,?,?,?,?)');$s->execute([$name,$desc,$cat,$price,$stock,$image]);} return redirect()->to(site_url('admin/shop'))->with('success','Produk disimpan.'); }
    public function deleteProduct($id) { $this->admin(); $s=$this->store()->db->prepare('UPDATE products SET active=0 WHERE id=?'); $s->execute([(int)$id]); return redirect()->to(site_url('admin/shop')); }
    public function status($id) { $this->admin(); $status=(string)$this->request->getPost('status'); if(in_array($status,['Pending','Processing','Completed','Cancelled'],true)){ $s=$this->store()->db->prepare('UPDATE orders SET status=? WHERE id=?'); $s->execute([$status,(int)$id]); } return redirect()->to(site_url('admin/shop')); }
}
